//! Number formatting helpers that reproduce `std::cout` semantics.

/// Renders `value` the way `std::cout << std::fixed << std::setprecision(p)`
/// does for a `float`.
///
/// Rust's `{:.p$}` already rounds the exact binary value half-to-even, which is
/// what glibc's `%.*f` does under the default rounding mode, so the finite path
/// is a straight delegation. Only the non-finite spellings differ: iostreams
/// emit `inf`/`nan` where Rust's `Display` emits `inf`/`NaN`.
pub fn fixed(value: f32, precision: usize) -> String {
    if value.is_nan() {
        // glibc keeps the sign bit of a NaN; `f32::is_sign_negative` reads it
        // directly rather than going through a comparison.
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }
    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }
    format!("{:.*}", precision, value)
}

/// `std::string(n, c)` — `c` repeated `n` times.
pub fn repeat(c: char, n: usize) -> String {
    let mut out = String::with_capacity(n * c.len_utf8());
    for _ in 0..n {
        out.push(c);
    }
    out
}

