//! `indicators::Percentage` — wraps a 0.0..=1.0 fraction and prints it as a
//! percentage with one decimal place, e.g. `0.75f` -> `75.0%`.

use super::format;

/// Decimal places used by `Percentage::str()` and by the percentage suffix of
/// `ProgressBar::str()`.
pub const PRECISION: usize = 1;

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Percentage {
    /// Fraction in the unit interval, held as `float` to match the C++ type.
    value: f32,
}

impl Percentage {
    /// `indicators::Percentage pct(value);`
    pub fn new(value: f32) -> Self {
        Self { value }
    }

    /// The underlying fraction.
    pub fn value(&self) -> f32 {
        self.value
    }

    pub fn set_value(&mut self, value: f32) {
        self.value = value;
    }

    /// The fraction scaled to 0..100. Kept in `f32` so the arithmetic matches
    /// the C++ `float` expression before it is widened for printing.
    pub fn percent(&self) -> f32 {
        self.value * 100.0
    }

    /// `pct.str()` — e.g. `75.0%`.
    pub fn str(&self) -> String {
        format!("{}%", format::fixed(self.percent(), PRECISION))
    }
}

impl std::fmt::Display for Percentage {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.str())
    }
}

