//! `indicators::ProgressBar` — a bracketed bar plus a percentage suffix.
//!
//! For `progress = 75`, `total = 100`, `width = 30` this renders
//! `[======================>       ] 75.0%`: `floor(0.75 * 30) = 22` fill
//! characters, one lead character, then `30 - 22 - 1 = 7` padding characters.

use super::format;
use super::percentage::{Percentage, PRECISION};

/// Default bar geometry, used until the caller overrides it. `test2.cpp` sets
/// every field before calling `str()`, so these only matter for other callers.
const DEFAULT_TOTAL: usize = 100;
const DEFAULT_WIDTH: usize = 100;

/// Glyphs making up the bar body.
const OPEN_BRACKET: char = '[';
const CLOSE_BRACKET: char = ']';
const FILL: char = '=';
const LEAD: char = '>';
const REMAINDER: char = ' ';

#[derive(Clone, Debug, PartialEq)]
pub struct ProgressBar {
    progress: usize,
    total: usize,
    width: usize,
}

impl Default for ProgressBar {
    fn default() -> Self {
        Self {
            progress: 0,
            total: DEFAULT_TOTAL,
            width: DEFAULT_WIDTH,
        }
    }
}

impl ProgressBar {
    /// `indicators::ProgressBar bar;`
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set_progress(&mut self, progress: usize) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: usize) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: usize) {
        self.width = width;
    }

    pub fn progress(&self) -> usize {
        self.progress
    }

    pub fn total(&self) -> usize {
        self.total
    }

    pub fn width(&self) -> usize {
        self.width
    }

    /// Completion as a fraction in `0.0..=1.0`.
    ///
    /// An empty `total` would divide by zero; float division yields `inf` (or
    /// `NaN` when the progress is zero too), so the result is clamped and a
    /// `NaN` collapses to "nothing done".
    fn fraction(&self) -> f32 {
        let fraction = self.progress as f32 / self.total as f32;
        if fraction.is_nan() {
            return 0.0;
        }
        fraction.clamp(0.0, 1.0)
    }

    /// Completion as a [`Percentage`].
    pub fn percentage(&self) -> Percentage {
        Percentage::new(self.fraction())
    }

    /// The characters between the brackets, always exactly `width()` wide.
    fn bar(&self) -> String {
        // Truncating conversion == C++ `static_cast<size_t>`, i.e. floor for
        // the non-negative values `fraction()` produces.
        let filled = (self.fraction() * self.width as f32) as usize;
        if filled >= self.width {
            return format::repeat(FILL, self.width);
        }
        let mut bar = format::repeat(FILL, filled);
        bar.push(LEAD);
        bar.push_str(&format::repeat(REMAINDER, self.width - filled - 1));
        bar
    }

    /// `bar.str()` — e.g. `[======================>       ] 75.0%`.
    pub fn str(&self) -> String {
        format!(
            "{}{}{} {}%",
            OPEN_BRACKET,
            self.bar(),
            CLOSE_BRACKET,
            format::fixed(self.percentage().percent(), PRECISION)
        )
    }
}

impl std::fmt::Display for ProgressBar {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.str())
    }
}

