//! Command-line surface of the entry program.
//!
//! `test2.cpp` declares `int main(int argc, char* argv[])` and never touches
//! either parameter: the progress, total, width and percentage it renders are
//! all literals in the body. The published test cases confirm this — every one
//! of them passes different `progress`/`total`/`width`/`percentage` values and
//! every one expects the same two lines of output.
//!
//! So this module mirrors that contract exactly: it accepts the same arguments
//! (positionally, `--name value`, or `--name=value`), never rejects anything,
//! and the parsed values are deliberately not fed into the rendering.

/// The arguments the C++ binary accepts, with the defaults it falls back to.
#[derive(Clone, Debug, PartialEq)]
pub struct Args {
    pub progress: usize,
    pub total: usize,
    pub width: usize,
    pub percentage: f32,
}

impl Default for Args {
    fn default() -> Self {
        Self {
            progress: 0,
            total: 100,
            width: 30,
            percentage: 0.0,
        }
    }
}

/// Positional order matching the test-case argument listing.
const POSITIONAL: [&str; 4] = ["progress", "total", "width", "percentage"];

impl Args {
    /// Parses `std::env::args()`, skipping `argv[0]`.
    pub fn from_env() -> Self {
        Self::parse(std::env::args().skip(1))
    }

    /// Parses an argument sequence. Unknown or malformed arguments are ignored
    /// rather than reported, because the C++ binary exits 0 for any input.
    pub fn parse<I: IntoIterator<Item = String>>(args: I) -> Self {
        let mut parsed = Self::default();
        let mut positional = POSITIONAL.iter();
        let mut args = args.into_iter().peekable();

        while let Some(arg) = args.next() {
            let flag = arg.trim_start_matches('-');
            if flag.len() < arg.len() {
                // `--name=value` or `--name value`.
                if let Some((name, value)) = flag.split_once('=') {
                    parsed.assign(name, value);
                } else if let Some(value) = args.next_if(|next| !next.starts_with('-')) {
                    parsed.assign(flag, &value);
                }
            } else if let Some(name) = positional.next() {
                parsed.assign(name, &arg);
            }
        }
        parsed
    }

    fn assign(&mut self, name: &str, value: &str) {
        let value = value.trim();
        match name {
            "progress" => self.progress = value.parse().unwrap_or(self.progress),
            "total" => self.total = value.parse().unwrap_or(self.total),
            "width" => self.width = value.parse().unwrap_or(self.width),
            "percentage" => self.percentage = value.parse().unwrap_or(self.percentage),
            _ => {}
        }
    }
}

