mod tests {
    use super::*;

    fn bar(progress: usize, total: usize, width: usize) -> String {
        let mut bar = ProgressBar::new();
        bar.set_progress(progress);
        bar.set_total(total);
        bar.set_width(width);
        bar.str()
    }

    /// The exact bytes `test2_executable` writes on its first line.
    #[test]
    fn matches_cpp_reference() {
        assert_eq!(bar(75, 100, 30), "[======================>       ] 75.0%");
    }

    #[test]
    fn body_is_always_exactly_width_wide() {
        for width in 0..40 {
            for progress in 0..=20 {
                let rendered = bar(progress, 20, width);
                let body = rendered
                    .trim_start_matches(OPEN_BRACKET)
                    .split(CLOSE_BRACKET)
                    .next()
                    .unwrap();
                assert_eq!(body.chars().count(), width, "{progress}/20 at width {width}");
            }
        }
    }

    #[test]
    fn endpoints_are_empty_and_full() {
        assert_eq!(bar(0, 100, 4), "[>   ] 0.0%");
        assert_eq!(bar(100, 100, 4), "[====] 100.0%");
    }

    #[test]
    fn out_of_range_progress_is_clamped() {
        assert_eq!(bar(200, 100, 4), bar(100, 100, 4));
    }

    /// An empty total must not panic or print a non-finite percentage.
    #[test]
    fn zero_total_is_survivable() {
        assert_eq!(bar(0, 0, 4), "[>   ] 0.0%");
        assert_eq!(bar(5, 0, 4), "[====] 100.0%");
    }
}
