        assert_eq!(Percentage::new(0.125f32).str(), "12.5%");
        assert_eq!(Percentage::new(0.3333f32).str(), "33.3%");
    }

    #[test]
    fn non_finite_uses_iostream_spelling() {
        assert_eq!(Percentage::new(f32::INFINITY).str(), "inf%");
        assert_eq!(Percentage::new(f32::NAN).str(), "nan%");
    }
}
