mod tests {
    use super::*;

    fn parse(args: &[&str]) -> Args {
        Args::parse(args.iter().map(|a| a.to_string()))
    }

    #[test]
    fn defaults_when_empty() {
        assert_eq!(parse(&[]), Args::default());
    }

    #[test]
    fn accepts_positional_flag_and_equals_forms() {
        let expected = Args { progress: 25, total: 200, width: 40, percentage: 0.125 };
        assert_eq!(parse(&["25", "200", "40", "0.125"]), expected);
        assert_eq!(
            parse(&["--progress", "25", "--total", "200", "--width", "40", "--percentage", "0.125"]),
            expected
        );
        assert_eq!(
            parse(&["--progress=25", "--total=200", "--width=40", "--percentage=0.125"]),
            expected
        );
    }

    /// The C++ binary exits 0 for any input, so nothing here may fail.
    #[test]
    fn junk_falls_back_to_defaults() {
        assert_eq!(parse(&["foo", "bar", "baz", "qux", "quux"]), Args::default());
        assert_eq!(parse(&["--nope", "--progress"]), Args::default());
    }
}
